/bin/bash -c "python3 - <<'PY'
from PIL import Image
import numpy as np
im=np.asarray(Image.open('first_frame.png').convert('RGB')).astype(int)
r,g,b=im.transpose(2,0,1)
# masks
masks={
 'peach': (r>175)&(r>g+5)&(g>b+2),
 'pinkbright':(r>200)&(r>g+5)&(g>b+2),
 'blue':(b>r+20)&(b>g+5)&(g>50),
 'dark':(im.max(2)<60),
 'darkgray':(im.max(2)<100),
}
for name,m in masks.items():
 ys,xs=np.where(m)
 print('\\n',name,'count',len(xs),'box', (xs.min(),ys.min(),xs.max(),ys.max()))
 print('row spans every 4')
 for y in range(0,256,4):
  xx=np.where(m[y])[0]
  if len(xx): print(f'{y:3d}: {xx.min():3d}-{xx.max():3d} n{len(xx):3d}', end=' | ')
  if y%16==12: print()
 print()
# Blue exact mask bbox/centroid, per row spans
m=masks['blue']
print('\\nblue row spans')
for y in range(150,220):
 xx=np.where(m[y])[0]
 if len(xx): print(y, xx.min(),xx.max(),len(xx))
# peach contours via simple connected components with scipy?
try:
 from scipy import ndimage
 for name,m in masks.items():
  lab,n=ndimage.label(m)
  cs=np.bincount(lab.ravel()); ids=np.argsort(cs[1:])[::-1][:8]+1
  print('\\ncomponents',name,n)
  for i in ids:
   ys,xs=np.where(lab==i);print(i,cs[i],(xs.min(),ys.min(),xs.max(),ys.max()),'mean',xs.mean(),ys.mean())
except Exception as e: print(e)
PY"
